<script setup>
import { ref, onMounted } from 'vue'
import { useLearning } from '../store'
const store=useLearning(), tab=ref('knowledge'), overview=ref([]), questions=ref([]), json=ref(''), message=ref(''), editingId=ref(null)
const blank=()=>({id:'',name:'',subject:'math',chapter:'',description:'',position:14,prerequisites:[]})
const form=ref(blank())
async function load() { if(store.user.role!=='admin')return; await store.run(async () => { [overview.value,questions.value]=await Promise.all([store.api('/admin/overview'),store.api('/admin/questions')]) }) }
function edit(n) { form.value={id:n.id,name:n.name,subject:n.subject,chapter:n.chapter,description:n.description,position:n.position,prerequisites:[...n.prerequisites]};message.value='' }
async function save() { await store.run(async () => {await store.api(`/admin/knowledge/${form.value.id}`,{method:'PUT',body:JSON.stringify(form.value)});await store.refresh();message.value='知识点与先修关系已保存，环路校验通过。'}) }
function editQuestion(q) { const {id,...data}=q;editingId.value=id;json.value=JSON.stringify(data,null,2);message.value='' }
async function saveQuestions() { await store.run(async () => {const data=JSON.parse(json.value);const result=await store.api(editingId.value ? `/admin/questions/${editingId.value}` : '/admin/questions/import',{method:editingId.value?'PUT':'POST',body:JSON.stringify(data)});message.value=editingId.value?`题目已保存，ID ${result.id}${result.versioned?'（历史题保留，新建版本）':''}`:`已导入 ${result.imported} 道题`;await load()}) }
async function upload(event) { const file=event.target.files[0];if(file){json.value=await file.text();editingId.value=null} }
onMounted(load)
</script>
<template><div v-if="store.user.role!=='admin'" class="empty"><h1>需要管理员权限</h1><p>请使用演示管理员账号登录。</p></div><template v-else><div class="page-heading"><div><p class="eyebrow">管理员工作台</p><h1>维护学习内容与关系</h1><p>先修环路、缺失字段与非法答案由服务端统一校验。</p></div></div><div class="filter-tabs"><button :class="{active:tab==='knowledge'}" @click="tab='knowledge'">知识点与先修</button><button :class="{active:tab==='questions'}" @click="tab='questions'">题目与 JSON 导入</button><button :class="{active:tab==='overview'}" @click="tab='overview'">演示学习概况</button></div><p v-if="message" role="status" class="callout">{{ message }}</p><div v-if="tab==='knowledge'" class="admin-grid"><section class="panel"><button class="secondary" @click="form=blank()">新增知识点</button><button v-for="n in store.nodes" :key="n.id" class="admin-node" @click="edit(n)">{{ n.name }}<small>{{ n.id }}</small></button></section><form class="panel" @submit.prevent="save"><h2>知识点编辑</h2><div class="form-grid"><label>独立 ID<input v-model="form.id" required pattern="[a-z0-9_-]{2,50}"/></label><label>名称<input v-model="form.name" required/></label><label>章节归属<input v-model="form.chapter" required/></label><label>稳定排序序号<input type="number" v-model.number="form.position" min="0" required/></label></div><label>学习说明<textarea v-model="form.description" required rows="3"></textarea></label><fieldset><legend>必要先修（可多选）</legend><label class="checkbox-label" v-for="n in store.nodes.filter(n=>n.id!==form.id)" :key="n.id"><input type="checkbox" v-model="form.prerequisites" :value="n.id"/>{{ n.name }}</label></fieldset><button class="primary">校验并保存</button></form></div><div v-if="tab==='questions'" class="admin-grid"><section class="panel admin-question-list"><h2>{{ questions.length }} 道题目（含归档）</h2><button v-for="q in questions" :key="q.id" @click="editQuestion(q)" class="admin-node">#{{ q.id }} {{ store.name(q.knowledge_id) }}<small>{{ q.stem }} {{ q.active?'':'[已归档]' }}</small></button></section><section class="panel"><h2>{{ editingId ? `编辑题目 #${editingId}` : '批量导入 JSON' }}</h2><p>导入格式为对象数组。必填：knowledge_id、stem、options（4 项）、answer（0～3）、explanation、difficulty（1～3）、source。</p><div class="actions"><button class="secondary" @click="editingId=null;json=''">切换为批量导入</button><label class="file-input">读取 JSON 文件<input type="file" accept=".json,application/json" @change="upload"/></label></div><label>JSON 内容<textarea v-model="json" rows="19" spellcheck="false" class="code-input" placeholder='[{"knowledge_id":"sets", ...}]'></textarea></label><button class="primary" @click="saveQuestions">校验并保存题目</button><p class="muted">已答题目修改时自动生成新版本，保留旧题及历史判题结果。</p></section></div><section v-if="tab==='overview'" class="panel"><h2>明确标注的模拟学习历史</h2><div v-for="entry in overview" :key="entry.user.id" class="overview-row"><h3>{{ entry.user.username }} <span class="badge">演示账号</span></h3><p>目标：{{ store.name(entry.user.goal_id) }} · {{ entry.report.total }} 次作答 · {{ entry.report.effective }} 条有效样本 · {{ entry.report.simulated }} 条模拟记录</p><p>已通过：{{ entry.report.knowledge.filter(n=>n.passed_at).map(n=>n.name).join('、') || '暂无' }}</p></div></section></template></template>
